import 'dart:async';
import 'dart:convert';
import 'dart:math';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../models/profile.dart';

import 'tts_service.dart';

/// Situation voice lines. Pre-recorded ElevenLabs MP3s live in
/// `assets/voice/<cue>_NN.mp3` (generated by `tools/gen_voice.py` from
/// `assets/voice_lines.json`). Nothing is synthesized live; the macOS
/// voice is only an emergency fallback when a cue has no MP3 yet.
///
/// Chat replies never go through here: they are text-only by design.
class VoiceCues {
  final AudioPlayer _player = AudioPlayer();
  final TtsService _fallback = TtsService();
  /// 'ko:greeting' -> recordings. Korean in assets/voice/, others in
  /// assets/voice_<lang>/ (same B3 voice, eleven_v3).
  final Map<String, List<String>> _files = {};

  /// Current lip-sync mouth shape while a recording plays (Rhubarb
  /// shapes A..H, X = closed), null when silent.
  final ValueNotifier<String?> mouth = ValueNotifier(null);
  Timer? _mouthTimer;
  final Map<String, List<String>> _lines = {};
  final _rand = Random();

  bool enabled = true;
  bool macFallback = true;
  DateTime _last = DateTime.fromMillisecondsSinceEpoch(0);
  String? _lastFile;

  /// Cues the app can trigger (matches the keys in voice_lines.json).
  static const cues = [
    'greeting',
    'eating',
    'sick',
    'rain',
    'hot',
    'happy',
    'celebrating',
    'sad',
    'bored',
    'sleepy',
    'idle',
    'pet',
    'tickle',
    'thanks',
  ];

  Future<void> init() async {
    await _fallback.init();
    try {
      final manifest = await AssetManifest.loadFromAssetBundle(rootBundle);
      for (final path in manifest.listAssets()) {
        final m = RegExp(r'^assets/voice(?:_(en|zh))?/([a-z]+)_\d+\.mp3$')
            .firstMatch(path);
        if (m != null) {
          _files
              .putIfAbsent('${m.group(1) ?? 'ko'}:${m.group(2)}', () => [])
              .add(path);
        }
      }
    } catch (_) {}
    try {
      final j =
          jsonDecode(await rootBundle.loadString('assets/voice_lines.json'))
              as Map<String, dynamic>;
      for (final e in j.entries) {
        _lines[e.key] =
            (e.value as List).map((x) => x['text'].toString()).toList();
      }
    } catch (_) {}
  }

  /// Asset path of the last recording played (demo timeline uses it).
  String? lastPlayed;

  int get recordedCount => _files.entries
      .where((e) => e.key.startsWith('${Lang.code}:'))
      .fold(0, (a, e) => a + e.value.length);
  bool hasRecording(String cue) =>
      _files['${Lang.code}:$cue']?.isNotEmpty ?? false;

  /// Plays a random line for [cue]. Rate-limited so the pet doesn't chatter;
  /// pass [force] for direct user actions (feeding, the test button).
  Future<void> play(String cue, {bool force = false}) async {
    if (!enabled) return;
    final now = DateTime.now();
    if (!force && now.difference(_last) < const Duration(seconds: 45)) return;
    _last = now;
    final files = _files['${Lang.code}:$cue'];
    if (files != null && files.isNotEmpty) {
      var f = files[_rand.nextInt(files.length)];
      if (files.length > 1 && f == _lastFile) {
        f = files[(files.indexOf(f) + 1) % files.length];
      }
      _lastFile = f;
      lastPlayed = f;
      try {
        await _player.stop();
        await _player.play(AssetSource(f.replaceFirst('assets/', '')));
        _lipSync(f);
      } catch (_) {}
      return;
    }
    final lines = _lines[cue];
    // The fallback lines are Korean text for the Mac's Korean voice.
    if (Lang.ko && macFallback && lines != null && lines.isNotEmpty) {
      await _fallback.speak(lines[_rand.nextInt(lines.length)]);
    }
  }

  /// Steps [mouth] through `<file>.mouth.json` (tools/gen_mouth.py).
  Future<void> _lipSync(String mp3) async {
    _mouthTimer?.cancel();
    mouth.value = null;
    List cues;
    try {
      cues = jsonDecode(await rootBundle
          .loadString(mp3.replaceFirst(RegExp(r'\.mp3$'), '.mouth.json'))) as List;
    } catch (_) {
      return;
    }
    if (cues.isEmpty) return;
    final clock = Stopwatch()..start();
    var i = 0;
    _mouthTimer = Timer.periodic(const Duration(milliseconds: 30), (t) {
      final now = clock.elapsedMilliseconds / 1000;
      while (i + 1 < cues.length && (cues[i + 1][0] as num) <= now) {
        i++;
      }
      final shape = cues[i][1] as String;
      if (i == cues.length - 1 && shape == 'X') {
        t.cancel();
        mouth.value = null;
        return;
      }
      mouth.value = shape;
    });
  }

  Future<void> stop() async {
    _mouthTimer?.cancel();
    mouth.value = null;
    try {
      await _player.stop();
    } catch (_) {}
    await _fallback.stop();
  }
}
